local GlassMoldMaker = {}
local PRODUCTS = {
    iron_glass_mold = { name = "Železni model za steklo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 6, cost = 185, prestige = 3, happiness = 2, description = "Železni model za oblikovanje stekla." },
    bronze_glass_mold = { name = "Bronast model za steklo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 8, cost = 450, prestige = 5, happiness = 3, description = "Bronast model za fino steklo." },
    silver_glass_mold = { name = "Srebrni model za steklo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 12, cost = 1080, prestige = 10, happiness = 4, description = "Srebrni model za plemiške steklarje." },
    gilded_glass_mold = { name = "Pozlačeni model za steklo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 16, cost = 2330, prestige = 19, happiness = 5, description = "Pozlačeni model za dvorne steklarje." },
    jewel_set_glass_mold = { name = "Draguljasti model za steklo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 20, cost = 5000, prestige = 35, happiness = 7, description = "Draguljasti model za kraljeve steklarje." },
    royal_sovereign_glass_mold = { name = "Kraljevski suvereni model za steklo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 27, cost = 10700, prestige = 68, happiness = 13, description = "Suvereni model z biseri za krono." },
}
local BUILDINGS = {
    glassmold_workshop = { name = "Modelna delavnica", cost = { gold = 360, wood = 180, stone = 145, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    glassmold_house = { name = "Modelna hiša", cost = { gold = 1265, wood = 360, stone = 280, silver = 8, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_glassmold_atelier = { name = "Mojstrski modelni atelje", cost = { gold = 3160, wood = 420, stone = 535, silver = 38, gold = 8 }, upkeep = 74, qualityBonus = 30 },
    sovereign_glassmold_palace = { name = "Suverena modelna palača", cost = { gold = 13400, wood = 640, stone = 850, gold = 86, jewel = 19 }, upkeep = 261, qualityBonus = 55, prestigeBonus = 50 },
}
GlassMoldMaker.ironStock = 14; GlassMoldMaker.bronzeStock = 12; GlassMoldMaker.woodStock = 14; GlassMoldMaker.leatherStock = 8; GlassMoldMaker.silverStock = 8; GlassMoldMaker.goldStock = 6; GlassMoldMaker.jewelStock = 4; GlassMoldMaker.pearlStock = 4
GlassMoldMaker.productStock = {}; GlassMoldMaker.buildings = {}; GlassMoldMaker.maker = nil; GlassMoldMaker.activeMaking = {}; GlassMoldMaker.totalProducts = 0; GlassMoldMaker.dayTimer = 0
function GlassMoldMaker.init() GlassMoldMaker.ironStock=14; GlassMoldMaker.bronzeStock=12; GlassMoldMaker.woodStock=14; GlassMoldMaker.leatherStock=8; GlassMoldMaker.silverStock=8; GlassMoldMaker.goldStock=6; GlassMoldMaker.jewelStock=4; GlassMoldMaker.pearlStock=4; GlassMoldMaker.productStock={}; GlassMoldMaker.buildings={}; GlassMoldMaker.maker=nil; GlassMoldMaker.activeMaking={}; GlassMoldMaker.totalProducts=0; GlassMoldMaker.dayTimer=0; print("[GlassMoldMaker] Royal Glass Mold Maker System initialized (6 products, 4 buildings)") end
function GlassMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassMoldMaker.maker={name=n or ("Modelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Modelar najet: %s (spretnost: %d)",GlassMoldMaker.maker.name,s),"success") end; return true end
function GlassMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassMoldMaker.build(id) local ok,e=GlassMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassMoldMaker.buildings==0 then return false,"Potrebna modelna delavnica" end; if not GlassMoldMaker.maker then return false,"Potreben modelar" end; return true end
function GlassMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassMoldMaker.ironStock=GlassMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassMoldMaker.bronzeStock=GlassMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassMoldMaker.woodStock=GlassMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassMoldMaker.leatherStock=GlassMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassMoldMaker.silverStock=GlassMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassMoldMaker.goldStock=GlassMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassMoldMaker.jewelStock=GlassMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassMoldMaker.pearlStock=GlassMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassMoldMaker.maker then t=math.max(1,t-math.floor(GlassMoldMaker.maker.skill/13)) end; table.insert(GlassMoldMaker.activeMaking,{id="glassmold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassMoldMaker.completeMaking(m) local q=1.0+(GlassMoldMaker.getQualityBonus()/100); if GlassMoldMaker.maker then q=q+(GlassMoldMaker.maker.skill/140) end; q=math.min(2.5,q); GlassMoldMaker.productStock[m.productType]=(GlassMoldMaker.productStock[m.productType] or 0)+m.quantity; GlassMoldMaker.totalProducts=GlassMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassMoldMaker.maker then GlassMoldMaker.maker.itemsMade=GlassMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassMoldMaker.maker.skill=math.min(100,GlassMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassmold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassMoldMaker.update(dt) if not _G.state then return end; GlassMoldMaker.dayTimer=GlassMoldMaker.dayTimer+dt; if GlassMoldMaker.dayTimer>=30 then GlassMoldMaker.dayTimer=0; for i=#GlassMoldMaker.activeMaking,1,-1 do local m=GlassMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassMoldMaker.completeMaking(m); table.remove(GlassMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassMoldMaker.getStats() return {ironStock=GlassMoldMaker.ironStock,bronzeStock=GlassMoldMaker.bronzeStock,woodStock=GlassMoldMaker.woodStock,leatherStock=GlassMoldMaker.leatherStock,silverStock=GlassMoldMaker.silverStock,goldStock=GlassMoldMaker.goldStock,jewelStock=GlassMoldMaker.jewelStock,pearlStock=GlassMoldMaker.pearlStock,productStock=GlassMoldMaker.productStock,numBuildings=#GlassMoldMaker.buildings,hasMaker=GlassMoldMaker.maker~=nil,makerName=GlassMoldMaker.maker and GlassMoldMaker.maker.name or "—",makerSkill=GlassMoldMaker.maker and GlassMoldMaker.maker.skill or 0,activeMaking=#GlassMoldMaker.activeMaking,totalProducts=GlassMoldMaker.totalProducts} end
return GlassMoldMaker
